store("inspect",`(r,whiteMove)=>{const g=load("g14");const t=r.content.filter(c=>c.type==="text").map(c=>c.text).join("\\n");const rows=[...t.matchAll(/^\\s*([1-9])\\s+([.XO](?:\\s+[.XO]){8})\\s+[1-9]\\s*$/gm)];if(rows.length!==9)return {text:t};const b=Array(81).fill(".");for(const m of rows){const y=Number(m[1])-1; m[2].trim().split(/\\s+/).forEach((v,x)=>b[y*9+x]=v);}const pt=i=>"ABCDEFGHJ"[i%9]+(1+Math.floor(i/9));const adj=i=>[i%9>0?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(x=>x>=0);const seen=new Set(),groups=[],regions=[];for(let i=0;i<81;i++){if(seen.has(i))continue;const col=b[i],todo=[i],stones=[],boundary=new Set(),libs=new Set();seen.add(i);while(todo.length){const j=todo.pop();stones.push(j);for(const k of adj(j)){if(b[k]===col){if(!seen.has(k)){seen.add(k);todo.push(k);}}else{boundary.add(b[k]);if(b[k]===".")libs.add(k);}}}const obj={color:col,points:stones.map(pt).sort(),size:stones.length};if(col==="."){obj.boundary=[...boundary];regions.push(obj);}else{obj.liberties=[...libs].map(pt).sort();obj.libertyCount=libs.size;groups.push(obj);}}const last=t.match(/Last move: ([A-HJ][1-9]|pass)/i)?.[1];const num=Number(t.match(/Move number: (\\d+)/)?.[1]);if(whiteMove){g.moves.push({color:"W",move:whiteMove});if(last&&last!==whiteMove)g.moves.push({color:"B",move:last});}else if(g.moves.length===0&&last)g.moves.push({color:"B",move:last});g.board=b;const inv={nextMove:num,groups,regions};g.inventories.push(inv);store("g14",g);return inv;}`);
